import{_ as e,o as i,c as n,a2 as o}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Capítulo 103 | Refinamiento del Reino · Reino de la Percepción Originaria · Sistemas de Cultivo Diferenciados de las Diez Mil Razas","description":"","frontmatter":{"title":"Capítulo 103 | Refinamiento del Reino · Reino de la Percepción Originaria · Sistemas de Cultivo Diferenciados de las Diez Mil Razas","no":103,"module":1,"tags":["境界","感元境","万族","差异化修炼","覆盖度"],"related":["14-修炼境界统一划分","50-万族谱系总览","52-异族分类与共生","10-三百套本源修炼体系总览"]},"headers":[],"relativePath":"es/103_模块1-感元境-万族差异化修炼体系.md","filePath":"es/103_模块1-感元境-万族差异化修炼体系.md"}'),s={name:"es/103_模块1-感元境-万族差异化修炼体系.md"};function r(l,a,t,c,d,u){return i(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="capitulo-103-reino-de-la-percepcion-originaria-sistemas-de-cultivo-diferenciados-de-los-grupos-de-las-diez-mil-razas" tabindex="-1">Capítulo 103 | Reino de la Percepción Originaria: sistemas de cultivo diferenciados de los grupos de las Diez Mil Razas <a class="header-anchor" href="#capitulo-103-reino-de-la-percepcion-originaria-sistemas-de-cultivo-diferenciados-de-los-grupos-de-las-diez-mil-razas" aria-label="Permalink to &quot;Capítulo 103 | Reino de la Percepción Originaria: sistemas de cultivo diferenciados de los grupos de las Diez Mil Razas&quot;">​</a></h1><blockquote><p>Módulo: Módulo uno · Refinamiento profundo de los reinos | Documentos base: 14, 50, 52, 10</p></blockquote><h2 id="introduccion-las-diez-mil-razas-no-son-diez-mil-tipos-de-humanos" tabindex="-1">Introducción: las Diez Mil Razas no son diez mil tipos de humanos <a class="header-anchor" href="#introduccion-las-diez-mil-razas-no-son-diez-mil-tipos-de-humanos" aria-label="Permalink to &quot;Introducción: las Diez Mil Razas no son diez mil tipos de humanos&quot;">​</a></h2><p>El Axioma de la República de las Diez Mil Razas de Heng Yuan Zhou (El Cosmos Originario de las Diez Mil Almas y el Ancla Equilibrada) es el más fácil de malentender en el concepto: las Diez Mil Razas no son &quot;diez mil tipos de humanos&quot;, sino miles de millones de formas de vida en cinco linajes —carbonado, energético, mecánico, consciente e híbrido. El Reino de la Percepción Originaria, como arranque de los Nueve Reinos, debe acoger esta diversidad en postura de &quot;un reino, mil métodos&quot;: llamado igual, la &quot;percepción&quot; de la raza bestial es olfato e intuición, la de la raza espíritu es resonancia energética, la de la raza máquina es escaneo de datos.</p><p>Medir las Diez Mil Razas con el estándar de una sola especie es en sí un arrogante desperdicio de nivel energético. Con base en el <em>Panorama de los linajes de las Diez Mil Razas</em> (doc. 50) y la <em>Clasificación y simbiosis de las razas extrañas</em> (doc. 52), este artículo despliega los sistemas de cultivo diferenciados de las Diez Mil Razas en el Reino de la Percepción Originaria.</p><p>Los Seis Axiomas Supremos son el fundamento legislativo de la diferenciación de las Diez Mil Razas: el Axioma del Antidepredación —cada raza toma energía solo del ciclo cósmico, jamás devora el origen ajeno; el Axioma de la República de las Diez Mil Razas —igual derecho evolutivo sin mirar el linaje; el Axioma de la Ascensión Dimensional Colectiva —el talento de cada raza retroalimenta a la civilización, erradicando el gran-material-pequeño-uso; el Axioma de la Autodisciplina Causal —el cultivo interétnico respeta la frontera causal ajena; el Axioma de la Prioridad de la Ley —el marco legal del sistema diferenciado de las Diez Mil Razas es estable y autoconsistente, jamás reescrito por conveniencia argumental, capaz de expandirse infinitamente sin colapsar. La Ley de Igualdad Infinita Universal para todos los Seres establece que todo ser porta en sí mismo el Poder Infinito Fundamental; los tranquilos conservan un infinito básico garantizado y no serán eliminados por los tiempos, mientras que los esforzados y los jóvenes supremos pueden apilar niveles superiores de infinito. El origen infinito lo porta todo ser; la depredación pierde naturalmente su sentido.</p><h2 id="i-diferencias-de-la-percepcion-originaria-segun-los-cinco-linajes" tabindex="-1">I. Diferencias de la Percepción Originaria según los cinco linajes <a class="header-anchor" href="#i-diferencias-de-la-percepcion-originaria-segun-los-cinco-linajes" aria-label="Permalink to &quot;I. Diferencias de la Percepción Originaria según los cinco linajes&quot;">​</a></h2><p>Según la clasificación quíntuple de las Diez Mil Razas del doc. 53 (razas materiales carbonadas, razas condensadas de energía, razas mecánicas, razas de información consciente, razas híbridas mutantes), los puntos de partida de cada raza en el Reino de la Percepción Originaria son naturalmente distintos:</p><table tabindex="0"><thead><tr><th>Linaje</th><th>Grupos representativos</th><th>Rasgos de la Percepción Originaria</th><th>Sistemas afines</th></tr></thead><tbody><tr><td>Material carbonado</td><td>Humanos, razas bestiales, razas de madera</td><td>La percepción arranca del cuerpo y los cinco sentidos; requiere tiempo para formar la conciencia de percepción energética</td><td>Sistema de Circulación Vital, Sistema de Iteración Deductiva</td></tr><tr><td>Condensado de energía</td><td>Razas espíritu, vidas elementales</td><td>Cuerpo energético innato; la &quot;percepción&quot; es casi instintiva, fácil saltar los fundamentos para condensar directo</td><td>Sistema de Regulación Espacio-Jurídica, Categoría de Deducción del Origen</td></tr><tr><td>Construido mecánico</td><td>Raza máquina, vida mecánica</td><td>&quot;Percebe&quot; la energía por vía datada; alta precisión pero falta de intuición</td><td>Categoría de Ingeniería Aplicada, Sistema de Iteración Deductiva</td></tr><tr><td>De información consciente</td><td>Entidades de conciencia, existencias de alta dimensión</td><td>La percepción es la actividad consciente misma; la Percepción Originaria solapa altamente su forma originaria</td><td>Categoría de Ascensión de la Conciencia</td></tr><tr><td>Híbrido mutante</td><td>Mestizos transplanar, vidas anómalas</td><td>Puntos de partida muy dispersos; requiere evaluación caso por caso</td><td>Evaluación de compatibilidad sistémica en primer lugar</td></tr></tbody></table><p>Las diferencias deben respetarse, mas no usarse para fabricar una &quot;raza superior&quot;: la raza espíritu percibe rápido pero el cuerpo portador es débil; la raza máquina es precisa pero la evolución espiritual es ardua; la raza consciente arranca alta pero tiene más lecciones de reparación una vez fuera del plano material. El estándar unificado de la Percepción Originaria (doc. 14) evalúa la aptitud sustantiva de &quot;percebir-absorber-discernir&quot;, no la forma concreta de la percepción —esta es la versión racial del principio &quot;valer lo sustantivo, no el nombre&quot;.</p><h2 id="ii-vias-diferenciadas-cada-raza-tiene-su-camino-todo-camino-llega-al-origen" tabindex="-1">II. Vías diferenciadas: cada raza tiene su camino, todo camino llega al Origen <a class="header-anchor" href="#ii-vias-diferenciadas-cada-raza-tiene-su-camino-todo-camino-llega-al-origen" aria-label="Permalink to &quot;II. Vías diferenciadas: cada raza tiene su camino, todo camino llega al Origen&quot;">​</a></h2><ul><li>Vía bestial: anclada en la intuición corporal, primero el sentir corporal luego la resonancia; la Percepción Originaria es &quot;despertar el lenguaje energético en la sangre&quot;.</li><li>Vía de la madera: anclada en el ritmo de crecimiento, absorción lenta y estable; la Percepción Originaria sincroniza con los anillos del tronco, un reino puede cultivarse cien años sin prisa.</li><li>Vía espíritu: anclada en la resonancia energética, la Percepción Originaria subraya la &quot;convergencia&quot; sobre la &quot;apertura&quot;, aprendiendo a controlar la sobrecarga de la percepción innata.</li><li>Vía máquina: anclada en la calibración de datos, convirtiendo la percepción energética en modelo recomputable; la Percepción Originaria es &quot;calibrar los sensores&quot;.</li><li>Vía consciente: anclada en la lucidez de la conciencia, la Percepción Originaria es &quot;la conciencia aterrizando&quot;, aprendiendo a expresar la percepción en el lenguaje del plano material.</li></ul><p>Cada vía lleva al mismo conjunto de certificación de reino, pero tras ella yace la lógica nativa propia. Esta es precisamente la forma de base de la doble circulación del origen de las Diez Mil Razas: cada raza toma del cosmos a su manera y devuelve a la civilización a su manera; el círculo nunca es unidireccional.</p><h2 id="iii-cultivo-interetnico-el-verdadero-sentido-de-la-red-de-mentores" tabindex="-1">III. Cultivo interétnico: el verdadero sentido de la red de mentores <a class="header-anchor" href="#iii-cultivo-interetnico-el-verdadero-sentido-de-la-red-de-mentores" aria-label="Permalink to &quot;III. Cultivo interétnico: el verdadero sentido de la red de mentores&quot;">​</a></h2><p>La diferenciación de las Diez Mil Razas no significa que cada una cultive por su lado; el cultivo interétnico es precisamente la escena más valiosa de la Percepción Originaria:</p><ul><li>Mentores interétnicos: un mentor espíritu calibra la percepción energética de un alumno bestial; un mentor humano ayuda a un alumno espíritu a comprender el soporte corporal —la esencia de la red de mentores (doc. 10) es el flujo de experiencia a nivel de civilización.</li><li>Evaluación de compatibilidad: el mecanismo de evaluación de compatibilidad sistémica ofrece planes caso por caso para mestizos y vidas anómalas, erradicando el &quot;etiquetado por raza&quot;.</li><li>Certificación igual: la certificación de reino y la asignación de recursos reconocen solo datos y contribuciones, no el linaje; los jóvenes supremos de las Diez Mil Razas (capítulo 102) comparten el mecanismo de doble vía.</li></ul><h2 id="iv-comparacion-la-estrechez-racial-es-el-techo-de-los-sistemas-inclusivos" tabindex="-1">IV. Comparación: la estrechez racial es el techo de los sistemas inclusivos <a class="header-anchor" href="#iv-comparacion-la-estrechez-racial-es-el-techo-de-los-sistemas-inclusivos" aria-label="Permalink to &quot;IV. Comparación: la estrechez racial es el techo de los sistemas inclusivos&quot;">​</a></h2><p>Esta es precisamente la manifestación directa del &quot;techo de Tang Luo&quot; en la dimensión de las Diez Mil Razas: incluso el sistema inclusivo de más alto nivel de la era antigua (la Academia sin Parangón de Tang Luo) abría solo a la raza humana —bestias, espíritus vegetales y voluntades planetarias todos excluidos de la &quot;inclusión&quot;. No es una mera omisión bondadosa, sino la inevitabilidad estructural de la cosmovisión depredadora: en la &quot;cosmovisión de coto de caza&quot;, quien no es de mi raza es o bien presa, o bien herramienta, jamás compañero de cultivo.</p><p>La respuesta que da el baremo de cobertura total de las Diez Mil Razas de Heng Yuan Zhou es: la Percepción Originaria no es el punto de partida de los humanos, sino de las Diez Mil Razas; la cobertura del 99 % no es un eslogan, sino que cada raza tiene una puerta abierta de par en par.</p><h2 id="v-cinco-puntos-de-aterrizaje-esenciales" tabindex="-1">V. Cinco puntos de aterrizaje esenciales <a class="header-anchor" href="#v-cinco-puntos-de-aterrizaje-esenciales" aria-label="Permalink to &quot;V. Cinco puntos de aterrizaje esenciales&quot;">​</a></h2><ul><li>Antidesperdicio de nivel energético: el talento de cada raza es un recurso escaso; medir las Diez Mil Razas con un solo estándar es el mayor gran-material-pequeño-uso.</li><li>Antidepredación: todas las vías diferenciadas reposan en la circulación y la simbiosis, ninguna en devorar el origen de otra raza.</li><li>Comparación con el techo de Tang Luo: la inclusión de la estrechez racial no es inclusión sino gracia; el objeto de la gracia es siempre &quot;los nuestros&quot;.</li><li>Cobertura total de las Diez Mil Razas: cinco linajes más vidas anómalas más mestizos transplanar; la Percepción Originaria encara el 99 % de cobertura total de las Diez Mil Razas.</li><li>Apertura total hiperpluralista: los métodos de la Percepción Originaria de cada raza se comparten abiertamente; el primer eslabón de la cadena plenamente abierta no distingue raza.</li></ul><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>El panorama de las Diez Mil Razas en la Percepción Originaria prueba una cosa: la diversidad cósmica no es un obstáculo para la evolución, sino su combustible. Cuando cada raza percibe el mundo y devuelve a la civilización a su manera mejor, el universo simbiótico de las Diez Mil Razas pasa de &quot;permitir la diferencia&quot; a &quot;necesitar la diferencia&quot; —y esta es precisamente la base biológica sobre la que se alza el Reino del Ancla Equilibrada Hiperpluralista.</p><h2 id="enlaces" tabindex="-1">Enlaces <a class="header-anchor" href="#enlaces" aria-label="Permalink to &quot;Enlaces&quot;">​</a></h2><ul><li>Documentos relacionados: <a href="./14-修炼境界统一划分.html">14-Clasificación unificada de reinos de cultivo</a> · <a href="./50-万族谱系总览.html">50-Panorama de los linajes de las Diez Mil Razas</a> · <a href="./52-异族分类与共生.html">52-Clasificación y simbiosis de las razas extrañas</a> · <a href="./10-三百套本源修炼体系总览.html">10-Panorama de los Trescientos Sistemas de Cultivo del Origen</a></li><li>Sitio oficial: <a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',25)])])}const z=e(s,[["render",r]]);export{m as __pageData,z as default};
